        void ScriptA2Emi::a2_emi() {
            if (ks::globals::exit_scenario) return;
            SKIP_IF_LOAD_ANOTHER_SCENE(SCRIPT_A2_EMI);
            ks::SceneManager::set_script(SCRIPT_A2_EMI);
            ks::SceneManager::init_savedata(ks::progress);
            ks::SceneManager::set(ks::SceneManager("script_a2_emi"));
        
            ScriptA2Emi::a2_emi_morning_run(); // INLINE CALL
            ScriptA2Emi::a2_emi_clouds_time_travel_and_thou(); // INLINE CALL
            ScriptA2Emi::a2_emi_questions_that_need_answering(); // INLINE CALL
            ScriptA2Emi::a2_emi_second_times_the_worst(); // INLINE CALL
            ScriptA2Emi::a2_emi_an_apple_a_day(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA2Emi::a2_emi_track_meeting(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA2Emi::a2_emi_down_that_medicine_now(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA2Emi::a2_emi_piracy_on_the_high_seas(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA2Emi::a2_emi_famous_last_words(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA2Emi::a2_emi_tracking_absences(); // INLINE CALL
            ScriptA2Emi::a2_emi_dropping_by(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA2Emi::a2_emi_the_first_morning_after(); // INLINE CALL
            ScriptA2Emi::a2_emi_the_real_beginning(); // INLINE CALL
        }
